      fac[0] = 1L;
      ifac[0] = 1L;
      for(int k = 1; k < MAXN; k++){
         fac[k] = (fac[k-1] * (long)k + MOD)%MOD;
         ifac[k] = modInverse(fac[k],MOD);
      }

      /*
      ifac[MAXN-1] = modInverse(fac[MAXN-1],MOD);
