      }*/

      int start = (n+1)/2;
      if(start % 2 == 1) start++;

      long answer = 0L;
      for(int k = start; k <= n; k+=2){
         long prod1 = 1L;
         if(n-k>=1){
            //doesn't do first skip
            prod1 = choose(k,n-k);
            //does first skip
            prod1 = (prod1 + choose(k-1,n-k-1) + MOD)%MOD;
         }
         long prod2 = (prod1*2L + MOD)%MOD;
         long prod3 = (prod2*fac[k] + MOD)%MOD;
         answer = (answer + prod3 + MOD)%MOD;
      }

      out.println(answer);








      out.close();
   }

   //a choose b, a!/(b!(a-b)!)
   public static long choose(int a, int b){
      long prod = (fac[a]*ifac[b] + MOD)%MOD;
      long prod2 = (prod*ifac[a-b] + MOD)%MOD;
      return prod2;
   }

   public static long modInverse(long a, long m)
    {
        long m0 = m;
        long y = 0;
        long x = 1;
        if (m == 1)
            return 0;

        while (a > 1) {
            // q is quotient
            long q = a / m;

            long t = m;

            // m is remainder now, process
            // same as Euclid's algo
            m = a % m;
            a = t;
            t = y;

            // Update x and y
            y = x - q * y;
            x = t;
        }

        // Make x positive
        if (x < 0)
            x += m0;

        return x;
    }


}

